const src = $('Merge Extracted Data').first().json;
const raw = $input.first().json.output !== undefined ? $input.first().json.output : ($input.first().json.message ? $input.first().json.message.content : JSON.stringify($input.first().json));
let text = String(raw == null ? '' : raw).trim();
text = text.replace(/^\`\`\`(?:json)?/i, '').replace(/\`\`\`$/, '').trim();
const m = text.match(/\{[\s\S]*\}/);
let verdict = {};
if (m) {
  try { verdict = JSON.parse(m[0]); } catch (e) {
    try { verdict = JSON.parse(m[0].replace(/\\"/g, '"').replace(/\\n/g, '\n')); } catch (e2) { verdict = {}; }
  }
}
const aiNominal = String(verdict.nominal || '').replace(/[^\d]/g, '');
const aiAccount = String(verdict.account || '').replace(/[^\d]/g, '');
const nominal = src.Nominal || aiNominal;
const account = src['No Rek / VA '] || aiAccount;
let ai_note = String(verdict.note || '').trim();
if (!nominal && !ai_note) ai_note = 'no nominal amount found';
if (!account && ai_note.indexOf('account') === -1) ai_note = (ai_note ? ai_note + '; ' : '') + 'no account or VA number found';
const verdict_ok = !!nominal && !!account && String(verdict.ok) !== 'false';
return [{ json: { ...src, Nominal: nominal, 'No Rek / VA ': account, verdict_ok, ai_note }, binary: $('Merge Extracted Data').first().binary || {} }];

const req = $('Parse AI Verdict').first().json;
const rows = items.map(i => i.json);
const norm = s => String(s == null ? '' : s).replace(/\s+/g, '');
const digits = s => String(s == null ? '' : s).replace(/[^\d]/g, '');
const reqNom = digits(req.Nominal);
const reqAcc = digits(req['No Rek / VA ']);
const reqReq = norm(req.Requester || '');
const dup = rows.find(r => {
  if (!reqNom || !reqAcc) return false;
  if (digits(r.Nominal) !== reqNom) return false;
  const va = String(r['No Rek/ VA'] || '').trim();
  const vaMatches = /^\d+$/.test(va) && va === reqAcc;
  const whoMatches = r['Requester'] && norm(r['Requester']) === reqReq;
  return vaMatches || (reqReq && whoMatches);
});
return [{ json: { ...req, is_duplicate: !!dup, duplicate_logged_on: dup ? String(dup['Tanggal Request'] || '').slice(0, 10) : '' }, binary: $('Parse AI Verdict').first().binary || {} }];

const rows = items.map(i => i.json).filter(r => r['Tanggal Request'] || r.Nominal);
const cutoff = new Date(Date.now() - 7 * 24 * 60 * 60 * 1000).toISOString().slice(0, 10);
const week = rows.filter(r => { const d = String(r['Tanggal Request'] || '').slice(0, 10); return d && d >= cutoff; });
const amount = s => { const n = String(s == null ? '' : s).replace(/[^\d]/g, ''); return n ? Number(n) : 0; };
const total = week.reduce((a, r) => a + amount(r.Nominal), 0);
const lines = week.map(r => '- ' + String(r['Tanggal Request'] || '').slice(0, 10) + ' | Rp' + (r.Nominal || '0') + ' | ' + (r['Account / Brand di MP'] || '') + ' | ' + (r.Requester || '')).join(String.fromCharCode(10));
return [{ json: { recap_date: new Date().toISOString().slice(0, 10), week_count: week.length, week_total: total, lines: lines || 'No requests logged this week.', recap_subject: 'Weekly Shopee ads recap ' + new Date().toISOString().slice(0, 10) } }];
